from functools import reducenumbers = [5, 12, 7, 20, 3, 18, 2, 15, 9, 30, 11, 6]# 1 Заданиеdef greater_than_ten(numbers):    for n in numbers:        if n > 10:            yield nprint(list(greater_than_ten(numbers)))# 2 Заданиеdef square_numbers(numbers):    for n in numbers:        yield n**2print(list(square_numbers(numbers)))# 3 Заданиеprint(list(filter(lambda x: x%2==0, map(lambda x: x**2, numbers))))# 4 Заданиеprint('\n'.join(list(map(lambda x: f'value = {x}', numbers))))# 5 Заданиеprint('1) ', reduce(lambda x, y: x+y, numbers))print('2) ', reduce(lambda x, y: y if y>x else x, numbers))# 6 Заданиеdef multiples_of_three(n, count = 0):    for n in numbers:        if n % 3 == 0 and count < 3:            count += 1            yield nprint(list(multiples_of_three(numbers)))# 7+8 Заданиеdef word_generator(text):    for word in text.split():        yield wordwords = word_generator('Пришла и оторвала голову нам чумачечая весна')for word in words:    print(word)words = list(word_generator('Пришла и оторвала голову нам чумачечая весна'))print(list(filter(lambda x: len(x)>4, words)))print(list(map(lambda x: x.upper(), words)))# Доп. задание## 1 реализация, первое что пришло на умdef f(n):    a = [0, 1]    yield a[0]    yield a[1]    for _ in range(n):        yield sum(a[-2:])        a.append(sum(a[-2:]))print(list(f(10)))## 2 реализация, по идее быстрее работает и памяти меньше требуетdef f(n):    a, b = 0, 1    yield a    yield b    for i in range(n):        yield a+b        a, b = b, a+bprint(list(f(10)))